<?php
$page_title='Dashboard'; require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/session.php'; require_once __DIR__.'/../config/functions.php'; require_once __DIR__.'/../config/auth.php'; requireAdmin();
$stats=[]; foreach(['users','courses','academic_fields','sessions','bookings'] as $table){$stats[$table]=(int)$pdo->query("SELECT COUNT(*) FROM `$table`")->fetchColumn();} $pendingBookings=(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='pending'")->fetchColumn(); $recent=$pdo->query("SELECT s.title,s.scheduled_at,u.full_name AS mentor_name,s.status FROM sessions s JOIN users u ON u.id=s.mentor_id ORDER BY s.scheduled_at DESC LIMIT 6")->fetchAll();
?>
<?php include __DIR__.'/includes/header.php'; ?><div class="admin-shell"><?php include __DIR__.'/includes/sidebar.php'; ?><main class="admin-main"><div class="admin-topbar"><div><h1 class="admin-title">Admin dashboard</h1><p class="admin-subtitle">A live overview of the SkillShare Hub platform.</p></div><span class="badge bg-success">System online</span></div><div class="admin-kpis"><div class="admin-card admin-kpi"><span>Users</span><strong><?php echo $stats['users']; ?></strong></div><div class="admin-card admin-kpi"><span>Courses</span><strong><?php echo $stats['courses']; ?></strong></div><div class="admin-card admin-kpi"><span>Academic fields</span><strong><?php echo $stats['academic_fields']; ?></strong></div><div class="admin-card admin-kpi"><span>Pending bookings</span><strong><?php echo $pendingBookings; ?></strong></div></div><div class="admin-card admin-table-wrap"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">Recent sessions</h2><a href="session/index.php" class="btn btn-sm btn-outline-primary">Manage sessions</a></div><table class="admin-table"><thead><tr><th>Session</th><th>Mentor</th><th>Scheduled</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $item): ?><tr><td><?php echo htmlspecialchars($item['title']); ?></td><td><?php echo htmlspecialchars($item['mentor_name']); ?></td><td><?php echo htmlspecialchars(date('M d, Y h:i A',strtotime($item['scheduled_at']))); ?></td><td><?php echo htmlspecialchars(ucfirst($item['status'])); ?></td></tr><?php endforeach; ?><?php if(!$recent): ?><tr><td colspan="4" class="text-muted text-center">No sessions yet.</td></tr><?php endif; ?></tbody></table></div></main></div><?php include __DIR__.'/includes/footer.php'; ?>
